head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL70301";
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil70301.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_EtnSelectSub", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) !== 0); } }, { id: "btn_EtnExcelDownload", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) !== 0); } }, { id: "btn_EtnExcelUploadPop", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) !== 0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_lastApplCnt_onchange
 * @description slc_lastApplCnt 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_lastApplCnt_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70301.slc_lastApplCnt_onchange' }); }
};

/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["applStatusCd"] === '00') { await scwin.etnApplDel(r["bzProcsNo"], r["applStatusCd"]); return; }
        await scwin.etnMst(r["isuCd"], r["bzProcsNo"], r["applStatusCd"], r["lastSaveStatCd"], r["rsnTabNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_EtnSelectSub_onclick
 * @description 「선택제출」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_EtnSelectSub_onclick = async function(e){
    try {
        await scwin.etnSelectSub()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70301.btn_EtnSelectSub_onclick' }); }
};

/**
 * @method
 * @name btn_EtnExcelDownload_onclick
 * @description 「엑셀다운」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_EtnExcelDownload_onclick = async function(e){
    try {
        await scwin.etnExcelDownload()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70301.btn_EtnExcelDownload_onclick' }); }
};

/**
 * @method
 * @name btn_EtnExcelUploadPop_onclick
 * @description 「엑셀업로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_EtnExcelUploadPop_onclick = function(e){
    try {
        fn_EtnExcelUploadPop('' + dma_readDataVO.get("listBzCd") + '')  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_EtnExcelUploadPop — JSP 팝업(window.open+폼 제출 — 회신)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70301.btn_EtnExcelUploadPop_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_65_onclick
 * @description krxpage_pagenavigator_65 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_65_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_loadListReq').set('pageIndex', pi);
        await scwin.tx_load_list();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil70301.krxpage_pagenavigator_65_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_SearchReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_etnApplDel
 * @description etn Appl Del 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_etnApplDel = async function () {
    const sbmOptions = {
        id: "tx_fn_etnApplDel",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_etnApplDelReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_EtnMst
 * @description Etn Mst 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_EtnMst = async function () {
    const sbmOptions = {
        id: "tx_fn_EtnMst",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_EtnMstReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/etn/EtnList.do?method=searchList&listBzCd=0",
        ref: "dma_loadListReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_65").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_pageList_fmt_column8
 * @description grd page List fmt column8 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fmt_column8 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "applStatusCd") ?? '') : '');
        if (v === '00') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "삭제" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.column8" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = '/etn/EtnList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name etnApplDel
 * @description etn Appl Del 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} applStatusCd applStatusCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnApplDel = async function (bzProcsNo, applStatusCd) {
    if (applStatusCd === '02') {
        await $c.win.alert('반송인 경우 삭제할 수 없습니다.');
        return;
    }
    if (!await $c.fil.confirmJob('D')) {
        return;
    }
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = '/etn/EtnList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'deleteList');
    $c.util.getComponent('dma_SearchReq').set('bzProcsNo', bzProcsNo);
    await scwin.tx_fn_etnApplDel();
};

/**
 * @method
 * @name etnMst
 * @description etn Mst 처리
 * @param {String} isuCd isuCd
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} applStatusCd applStatusCd
 * @param {String} lastSaveStatCd lastSaveStatCd
 * @param {*} rsnTabNo rsnTabNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnMst = async function (isuCd, bzProcsNo, applStatusCd, lastSaveStatCd, rsnTabNo) {
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = '/etn/EtnList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'detailList');
    $c.util.getComponent('dma_SearchReq').set('isuCd', isuCd);
    $c.util.getComponent('dma_SearchReq').set('bzProcsNo', bzProcsNo);
    if (applStatusCd === '03') {
        if (rsnTabNo !== '05') {
            $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', Number(rsnTabNo));
        } else {
            $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', 0);
        }
    } else {
        $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', lastSaveStatCd);
    }
    $c.util.getComponent('dma_SearchReq').set('applStatusCd', applStatusCd);
    await scwin.tx_fn_EtnMst();
};

/**
 * @method
 * @name etnSelectSub
 * @description etn Select Sub 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnSelectSub = async function () {
    if ($c.util.getComponent("grd_pageList").getCheckedIndex("checkSub").length === 0) {  // as-is $("[name='checkSub']").is(':checked') — 그리드 체크 컬럼
        await $c.win.alert('선택된 항목이 없습니다.');
        return;
    }

    if (! await $c.fil.confirmJob('S') ) return;

    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = '/etn/EtnList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'submitMultiList');
    await moveUrl('/etn/EtnList.do', {});

};

/**
 * @method
 * @name etnExcelDownload
 * @description etn Excel Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnExcelDownload = async function () {
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = '/etn/EtnList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'etnExcelDownload');
    await moveUrl('/etn/EtnList.do', {});

};
